tasks.command:
PORT_PIDS=$(lsof -ti tcp:8012 | tr '
' ' ') && if [[ -n "$PORT_PIDS" ]]; then kill $PORT_PIDS; fi && cd ppl-meta-presence/src && source /Users/nickgklezakos/Documents/ppl-meta-code/scripts/load-presence-runtime-env.sh && PRESENCE_DETECTION_BACKEND_MODE=simulate PYTHONPATH=/Users/nickgklezakos/Documents/ppl-meta-code/ppl-meta-presence/src python3.11 -m uvicorn main:app --host 0.0.0.0 --port 8012 >/tmp/ppl-meta-presence-simulated.log 2>&1 & SERVER_PID=$! && trap 'kill $SERVER_PID 2>/dev/null || true' EXIT && python3.11 -c "import json,time,urllib.request; url='http://localhost:8012/health'; deadline=time.time()+30; last_error='';
while time.time() < deadline:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:
            data=json.load(response)
            assert data.get('status') == 'healthy'
            break
    except Exception as exc:
        last_error=str(exc)
        time.sleep(1)
else:
    raise SystemExit(f'Simulated presence service did not become healthy: {last_error}')" && cd .. && PRESENCE_VALIDATION_BASE_URL=http://localhost:8012/api/v1/presence PRESENCE_VALIDATION_USERNAME=${env:PRESENCE_VALIDATION_USERNAME} PRESENCE_VALIDATION_PASSWORD=${env:PRESENCE_VALIDATION_PASSWORD} python3.11 validate_presence_flow.py
